class I(int):
 def __new__(cls,n):
  print("new",n)
  return int.__new__(cls,n+1)
 def __init__(self,n): print("init",n); self.original=n
i=I(7)
print(int(i),i.original,type(i) is I)

class I(int):
 def __new__(cls,n): return "other"
 def __init__(self,n): print("never")
print(I(7))

class I(int):
 def __add__(self,other): print("I"); return 7
class J(I):
 def __radd__(self,other): print("J"); return 9
print(I(1)+J(2),J(2)+I(1))

class T(tuple):
 def __len__(self): return 7
 def __iter__(self): return iter((11,13))
t=T((7,9))
print(len(t),tuple.__len__(t),next(iter(t)),t[0],type(t[:]) is tuple)
